#include <stdio.h>

/* teste do desafio via-ponteiro — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   A funcao do aluno nao devolve nem imprime: o teste declara a variavel,
   entrega o ENDERECO dela e confere o valor que sobrou na variavel. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void viaPonteiro(int *p);

SM_TEST(dobra_o_valor_do_endereco) {
    int x = 21;
    viaPonteiro(&x);
    checa_int("x dobrou pela outra porta", x, 42,
              "escrever em *p escreve na casa de x: 21 passa a 42");
}

SM_TEST(dobra_valor_negativo) {
    int y = 0 - 3;   /* um valor negativo: tres abaixo de zero */
    viaPonteiro(&y);
    checa_int("o negativo tambem dobra", y, 0 - 6,
              "dobrar e multiplicar por 2, com sinal e tudo: -3 passa a -6");
}

SM_TEST(o_zero_dobrado_continua_zero) {
    int z = 0;
    viaPonteiro(&z);
    checa_int("o zero dobrado continua zero", z, 0,
              "a funcao le o valor da casa antes de escrever: zero vezes 2 e zero");
}
